// Package persistence provides access to the lightsql database of moneyd. The
// typed query code is generated by sqlc from internal/persistence/sql; run
// `go generate ./...` after changing the schema or queries.
package persistence

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"

	"github.com/pressly/goose/v3"

	lightsql "github.com/oxisto/lightsql/driver"
)

//go:generate sqlc generate -f ../../sqlc.yaml

//go:embed sql/migrations/*.sql
var migrations embed.FS

// DB wraps the generated queries together with the underlying connection.
type DB struct {
	*Queries

	conn *sql.DB
	dsn  string
}

// OpenDB opens the lightsql database at path (a directory, created if
// missing) and applies all pending migrations. Use ":memory:" for an
// ephemeral, in-memory database in tests.
//
// Unlike SQLite, lightsql's in-memory instances aren't private per
// connection: they're just a name, and re-opening one returns whatever a
// previous caller left behind. ":memory:" drops any existing instance under
// that name first, so it keeps SQLite's "always a fresh, isolated database"
// behavior — which every test in this codebase relies on.
func OpenDB(path string) (*DB, error) {
	dsn := "file:" + path
	if path == ":memory:" {
		dsn = path
		lightsql.Drop(dsn)
	}

	conn, err := sql.Open("lightsql", dsn)
	if err != nil {
		return nil, fmt.Errorf("could not open database: %w", err)
	}

	goose.SetBaseFS(migrations)
	goose.SetLogger(goose.NopLogger())

	if err = goose.SetDialect("postgres"); err != nil {
		return nil, err
	}

	if err = goose.Up(conn, "sql/migrations"); err != nil {
		return nil, fmt.Errorf("could not apply migrations: %w", err)
	}

	return &DB{Queries: New(conn), conn: conn, dsn: dsn}, nil
}

// Close closes the underlying database connection. For a directory-backed
// database this also compacts the write-ahead log, so the next OpenDB call
// replays only the rows that survived rather than every change ever made —
// skipping it is safe, just slower to reopen.
func (db *DB) Close() error {
	err := db.conn.Close()
	lightsql.Drop(db.dsn)
	return err
}

// maxTxAttempts bounds how often Tx runs fn when it keeps hitting write
// conflicts.
const maxTxAttempts = 3

// Tx runs fn inside a database transaction, committing if fn returns nil and
// rolling back otherwise.
//
// lightsql is MVCC: two transactions writing the same row don't block, the
// second one fails with SQLSTATE 40001 (serialization_failure). Tx retries
// those, so fn may run more than once and must not leave anything behind
// outside the transaction — reset any captured results at its start.
func (db *DB) Tx(ctx context.Context, fn func(q *Queries) error) error {
	return db.TxWith(ctx, nil, fn)
}

// TxWith is Tx with explicit transaction options. The default, READ
// COMMITTED, takes a fresh snapshot per statement, so fn can read a row and
// then overwrite a change someone committed in between. Pass
// sql.LevelRepeatableRead when fn writes based on what it read: the whole
// transaction then sees one snapshot, and an in-between change is a write
// conflict — which Tx retries, re-reading the current row.
func (db *DB) TxWith(ctx context.Context, opts *sql.TxOptions, fn func(q *Queries) error) (err error) {
	for attempt := 1; ; attempt++ {
		err = db.tx(ctx, opts, fn)
		if attempt < maxTxAttempts && isSerializationFailure(err) {
			continue
		}
		return err
	}
}

// isSerializationFailure reports whether err is a write conflict. The
// SQLState interface is the one pgx and lib/pq also satisfy.
func isSerializationFailure(err error) bool {
	var e interface{ SQLState() string }
	return errors.As(err, &e) && e.SQLState() == "40001"
}

func (db *DB) tx(ctx context.Context, opts *sql.TxOptions, fn func(q *Queries) error) error {
	tx, err := db.conn.BeginTx(ctx, opts)
	if err != nil {
		return err
	}

	if err := fn(db.Queries.WithTx(tx)); err != nil {
		_ = tx.Rollback()
		return err
	}

	return tx.Commit()
}

// CreatePersonWithAccess creates a person and grants userID access to it in
// one transaction. Done as two separate writes, a failed grant left a person
// nobody could reach — and since the next login found the person and skipped
// creating it, it never got the grant on retry either.
func (db *DB) CreatePersonWithAccess(ctx context.Context, arg CreatePersonParams, userID string) (person *Person, err error) {
	err = db.Tx(ctx, func(q *Queries) (err error) {
		person, err = q.CreatePerson(ctx, arg)
		if err != nil {
			return err
		}
		return q.GrantPersonAccess(ctx, GrantPersonAccessParams{
			UserID:   userID,
			PersonID: person.ID,
		})
	})
	return person, err
}
